    Rules (in order):
    1. If length > 15, remove the middle character.
    2. If the string contains an even number of 'b's (and at least one), append 'ab'.
    3. If the string ends with 'ac', replace it with 'cb'.
    4. If the string starts with 'ab', replace it with 'ca'.
    """
    def rule1(st: str) -> str | None:
        # length > 15, remove middle character
        if len(st) > 15:
            mid = len(st) // 2
            return st[:mid] + st[mid + 1 :]
        return None

    def rule2(st: str) -> str | None:
        # even number of 'b's (at least one), append 'ab'
        b_cnt = st.count('b')
        if b_cnt > 0 and b_cnt % 2 == 0:
            return st + 'ab'
        return None

    def rule3(st: str) -> str | None:
        # suffix 'ac' -> 'cb'
        if st.endswith('ac'):
            return st[:-2] + 'cb'
        return None

    def rule4(st: str) -> str | None:
        # prefix 'ab' -> 'ca'
        if st.startswith('ab'):
            return 'ca' + st[2:]
        return None

    rules = [rule1, rule2, rule3, rule4]
    seen: set[str] = set()
    current = s
    while True:
        if current in seen:
            break  # repeated state, discard it and keep previous unique state
        seen.add(current)
        for r in rules:
            new = r(current)
            if new is not None and new != current:
                current = new
                break
        else:
            # no rule applied
            break
    return current

